"""Pipeline wiring.

Secret: the order in which the stages run (alias split, lex, rewrite,
extract globals, load config, expand aliases, resolve, bind, run or hand
off to a remote transport) and how failures map to output and exit codes.
"""

import os
import time

from . import (aliases, binding, catalog, config_files, db, dispatch, file_cache,
               help_text, logfile, process, remote, rewrites, runtime_config,
               tokens, values)
from .command_tree import CommandTree
from .errors import CliError, Halt, MissingPositional
from .output import Output, color_enabled

_COMPLETION = ["cli", "completion"]


class CommandContext:
    """Everything a command handler may use."""

    def __init__(self, command, args, out, config, tree, cwd=None, cache=None,
                 launcher=None, db=None):
        self.command = command
        self.args = args
        self.out = out
        self.config = config
        self.tree = tree
        self.cwd = cwd if cwd is not None else os.getcwd()
        self.cache = cache
        self.launcher = launcher
        self.db = db

    def run_process(self, command, **kwargs):
        """Run an external command (see ``process.run``)."""
        kwargs.setdefault("out", self.out)
        kwargs.setdefault("cwd", self.cwd)
        return process.run(command, **kwargs)

    def launch_self(self, command, *args, **kwargs):
        """Re-dispatch an appctl command in a child process (see
        ``process.Launcher.launch_self``)."""
        return self.launcher.launch_self(command, *args, **kwargs)

    def runcommand(self, command, **kwargs):
        """Run an appctl command in a child process and return its output
        (see ``process.Launcher.runcommand``)."""
        return self.launcher.runcommand(command, **kwargs)

    def read_value(self, index):
        """Positional ``index``, or STDIN when it was not given, decoded
        according to ``--format``; ``None`` when neither is available."""
        raw = self.args.positional(index)
        if raw is None:
            raw = self.out.read_stdin()
            if raw is None:
                return None
        return values.read_value(raw, self.args.option("format"))


def build_tree():
    tree = CommandTree()
    catalog.register_all(tree)
    return tree


def _split_alias(argv):
    """Remove a leading ``@alias`` word; return ``(alias, argv)``."""
    for index, raw in enumerate(argv):
        if raw == "--":
            break
        if raw.startswith("--") and len(raw) > 2:
            continue
        if aliases.is_alias_name(raw):
            return raw, argv[:index] + argv[index + 1:]
        break
    return None, argv


def _is_completion(argv):
    """Tab-completion invocations are never written to the log file."""
    words = []
    for raw in argv:
        if raw == "--":
            break
        if not raw.startswith("--"):
            words.append(raw)
    return words[:len(_COMPLETION)] == _COMPLETION


def _last_option(options, name):
    found = None
    for key, value in options:
        if key == name:
            found = value
    return found


class _Invocation:
    def __init__(self, argv, env, stdout, stderr, tree, cwd, stdin, started):
        self.argv = argv
        self.env = env
        self.stdout = stdout
        self.stderr = stderr
        self.tree = tree
        self.cwd = cwd
        self.stdin = stdin
        self.started = started

    def _color(self, setting):
        return color_enabled(setting, self.stdout)

    def start(self, alias):
        self.locations = config_files.Locations(self.env)
        log = logfile.LogFile(logfile.log_path(self.locations.root_dir),
                              enabled=not _is_completion(self.argv))
        log.start_invocation()
        self.out = out = Output(self.stdout, self.stderr, stdin=self.stdin, log=log,
                                start=self.started, color=self._color("auto"))
        try:
            items = rewrites.apply(tokens.lex(self.argv))
            self.runtime, self.items = runtime_config.extract(items, self.env)
        except CliError as exc:
            out.report(exc)
            return exc.exit_code
        runtime_values = self.runtime.values
        out.configure(quiet=self.runtime.quiet(),
                      debug=runtime_values.get("debug", False),
                      color=self._color(runtime_values.get("color", "auto")))
        for warning in self.runtime.warnings:
            out.warning(warning)
        self.cache = file_cache.from_env(self.env, self.locations.root_dir,
                                         warn=out.warning)
        try:
            self.db = db.open_database(self.locations.root_dir)
        except CliError as exc:
            out.report(exc)
            return exc.exit_code
        try:
            return self.load_and_execute(alias)
        finally:
            self.db.close()
            if not _is_completion(self.argv):
                try:
                    self.cache.clean()
                except OSError:
                    pass

    def load_and_execute(self, alias):
        out = self.out
        try:
            self.loaded = config_files.load(self.locations, self.cwd)
            if "color" not in self.runtime.values:
                out.configure(color=self._color(self.loaded.values.get("color", "auto")))
            self.registry = aliases.AliasRegistry(
                self.loaded.aliases, aliases.runtime_aliases(self.env))
            for path in self.loaded.files:
                out.debug(f"Loaded config file: {path}", group="bootstrap")
            return self.execute(alias, ())
        except CliError as exc:
            out.report(exc)
            return exc.exit_code
        except Halt as exc:
            return exc.exit_code

    def execute(self, alias, stack):
        if alias is None:
            return self.invoke({})
        target = self.registry.resolve(alias)
        if not target.is_group():
            return self.invoke(target.connection)
        code = 0
        for member in target.members:
            if member == alias or member in stack:
                continue
            self.out.log(member)
            try:
                result = self.execute(member, stack + (alias,))
            except CliError as exc:
                self.out.report(exc)
                result = exc.exit_code
            code = result or code
        return code

    def invoke(self, connection):
        config = runtime_config.layer(
            self.runtime, self.loaded.values, connection,
            locations=self.locations, loaded=self.loaded, aliases=self.registry)
        self.out.configure(color=self._color(config.color()))
        if config.ssh():
            return remote.run(config.ssh(), self.argv, connection,
                              self.runtime.values, config, self.env, self.out,
                              self.stdout, self.stderr)
        return self.run_local(config)

    def run_local(self, config):
        out = self.out
        if self.tree is None:
            self.tree = build_tree()
        tree = self.tree
        items = self.items
        words = [t.text for t in items if not t.is_option()] or ["help"]
        options = [(t.name, t.value) for t in items if t.is_option()]
        node = None
        try:
            node, remaining = dispatch.resolve(tree, words, config.disabled_commands())
            out.debug(f"Resolved command '{node.path}' with arguments {remaining}",
                      group="bootstrap")
            out.log_only(f"Command: {node.path}")
            if not node.is_runnable():
                out.usage(help_text.composite_usage(node))
                return 0
            remaining = self.stdin_fallback(node.synopsis, remaining, options)
            bound = binding.bind(node.path, node.synopsis, node.defaults(),
                                 remaining, options)
            launcher = process.Launcher(
                self.runtime.values, self.env, self.cwd, out,
                config_path=self.locations.global_config_path)
            result = node.run(CommandContext(node, bound, out, config, tree,
                                             cwd=self.cwd, cache=self.cache,
                                             launcher=launcher, db=self.db))
            return int(result or 0)
        except MissingPositional:
            out.usage(help_text.usage_line(node))
            return 1

    def stdin_fallback(self, synopsis, words, options):
        """Read a missing required positional from STDIN, if any is piped."""
        if len(words) >= synopsis.required_positional_count():
            return words
        raw = self.out.read_stdin()
        if raw is None:
            return words
        fmt = (_last_option(options, "format")
               if "format" in synopsis.option_names() else None)
        return list(words) + [values.read_value(raw, fmt)]


def run(argv, env, stdout, stderr, tree=None, cwd=None, stdin=None):
    """Run one invocation and return its exit code.

    ``stdin`` defaults to ``sys.stdin`` at the time input is needed.
    """
    started = time.monotonic()
    alias, argv = _split_alias(list(argv))
    invocation = _Invocation(argv, env, stdout, stderr, tree,
                             cwd if cwd is not None else os.getcwd(), stdin, started)
    return invocation.start(alias)
"""Command resolution.

Secret: how positional words are walked down the command tree, and when
leftover words become arguments of the matched command rather than unknown
subcommands.
"""

from . import messages as _messages
from .errors import CliError
from .suggest import suggest


def resolve(tree, words, disabled=()):
    """Find the deepest command matching the leading ``words``.

    Returns ``(node, remaining_words)``. Raises ``CliError`` for an unknown
    top-level command, an unknown subcommand under a group that cannot
    itself run, or a command whose path is listed in ``disabled``.
    """
    disabled = set(disabled)
    node = tree.root
    words = list(words)
    consumed = 0
    for word in words:
        if not node.has_children():
            break
        child = node.find_child(word)
        if child is None:
            if node.is_runnable() and not node.is_root():
                break
            suggestion = suggest(word, node.child_names())
            if node.is_root():
                raise CliError(_messages.unregistered_command(word, suggestion))
            raise CliError(_messages.unregistered_subcommand(
                word, node.path, suggestion))
        node = child
        consumed += 1
        if node.path in disabled:
            raise CliError(_messages.command_disabled(node.path))
    return node, words[consumed:]
"""External command execution.

Secret: how child processes are spawned, timed and logged, how sensitive
substrings are hidden from debug output, the wording of the exit code -1
warning, and how appctl re-invokes itself with the current runtime
configuration.
"""

import json
import os
import shlex
import subprocess
import sys
import time

from . import messages as _messages
from .errors import Halt
from .output import Output

_GROUP = "process"
_MASK = "******"
_SIGNAL_EXIT = -1
_ENTRY_POINT = os.path.join(
    os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "appctl.py")
# Environment variables describing the runtime that a child appctl inherits.
_CONFIG_PATH_ENV = "APPCTL_CONFIG_PATH"


class ProcessRun:
    """Outcome of one external command."""

    def __init__(self, command, stdout, stderr, return_code, run_time, cwd=None, env=None):
        self.command = command
        self.stdout = stdout
        self.stderr = stderr
        self.return_code = return_code
        self.run_time = run_time
        self.cwd = cwd
        self.env = env

    @property
    def succeeded(self):
        return self.return_code == 0

    def __repr__(self):
        return (f"ProcessRun(command={self.command!r}, return_code={self.return_code}, "
                f"run_time={self.run_time:.3f})")


def _default_output():
    return Output(sys.stdout, sys.stderr)


def command_text(command):
    """The command as a single shell-style string."""
    if isinstance(command, (list, tuple)):
        return shlex.join(str(part) for part in command)
    return str(command)


def obfuscate(text, secrets):
    """Replace every listed substring of ``text`` with ``******``."""
    text = str(text)
    for secret in sorted({str(s) for s in secrets or () if s not in (None, "")},
                         key=len, reverse=True):
        text = text.replace(secret, _MASK)
    return text


def _decode(data):
    if data is None:
        return ""
    if isinstance(data, bytes):
        return data.decode(errors="replace")
    return data


def run(command, *, cwd=None, env=None, out=None, obfuscate_list=(), stdin=None):
    """Run ``command`` and return a ``ProcessRun``.

    ``command`` is either a shell command string or an argument list. The
    command is logged at debug level before it runs (with every substring in
    ``obfuscate_list`` masked); afterwards non-empty STDOUT and STDERR and the
    return code are logged. The returned result always holds the real values.
    """
    out = out or _default_output()
    text = command_text(command)

    def debug(message):
        out.debug(obfuscate(message, obfuscate_list), group=_GROUP)

    debug(f"Running command: {text}")
    started = time.monotonic()
    try:
        proc = subprocess.run(
            command, shell=isinstance(command, str), cwd=cwd,
            env=dict(env) if env is not None else None,
            input=stdin.encode() if isinstance(stdin, str) else stdin,
            stdin=None if stdin is not None else subprocess.DEVNULL,
            stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        stdout, stderr, code = _decode(proc.stdout), _decode(proc.stderr), proc.returncode
    except OSError as exc:
        stdout, stderr, code = "", f"{getattr(exc, 'strerror', None) or exc}\n", 127
    result = ProcessRun(text, stdout, stderr, code, time.monotonic() - started,
                        cwd=cwd, env=env)
    if stdout:
        debug(f"STDOUT: {stdout.rstrip(chr(10))}")
    if stderr:
        debug(f"STDERR: {stderr.rstrip(chr(10))}")
    debug(f"Return code: {code}")
    if code == _SIGNAL_EXIT:
        out.warning(_messages.spawned_exit_minus_one())
    return result


def run_check(command, **kwargs):
    """Run ``command`` and return whether it exited successfully."""
    return run(command, **kwargs).succeeded


# --- re-dispatching appctl -------------------------------------------------

def _flag(name, value):
    if value is True:
        return f"--{name}"
    if value is False:
        return f"--no-{name}" if name == "color" else None
    if value is None:
        return None
    return f"--{name}={value}"


def runtime_flags(runtime_values):
    """Global flags reproducing ``runtime_values`` on a command line."""
    flags = []
    for name, value in runtime_values.items():
        flag = _flag(name, value)
        if flag is not None:
            flags.append(flag)
    return flags


def _args_list(command):
    if isinstance(command, str):
        return shlex.split(command)
    return [str(part) for part in command]


def _assoc_flags(assoc_args):
    flags = []
    for key, value in (assoc_args or {}).items():
        flag = _flag(key, value)
        if flag is not None:
            flags.append(flag)
    return flags


class Launcher:
    """Runs appctl as a child process with the current runtime configuration:
    the same interpreter and entry point, the same global flags, config file
    path, environment and working directory."""

    def __init__(self, runtime_values, env, cwd, out, config_path=None):
        self.runtime_values = dict(runtime_values or {})
        self.env = dict(env or {})
        self.cwd = cwd
        self.out = out or _default_output()
        self.config_path = config_path

    def argv(self, command, args=(), assoc_args=None, runtime_args=None):
        values = dict(self.runtime_values)
        values.update(runtime_args or {})
        return ([sys.executable, _ENTRY_POINT] + runtime_flags(values)
                + _args_list(command) + [str(a) for a in args]
                + _assoc_flags(assoc_args))

    def environment(self):
        env = dict(self.env)
        if self.config_path and not env.get(_CONFIG_PATH_ENV):
            env[_CONFIG_PATH_ENV] = self.config_path
        return env

    def launch(self, command, args=(), assoc_args=None, *, runtime_args=None,
               obfuscate_list=(), stdin=None):
        """Run appctl ``command`` and return the ``ProcessRun``."""
        return run(self.argv(command, args, assoc_args, runtime_args),
                   cwd=self.cwd, env=self.environment(), out=self.out,
                   obfuscate_list=obfuscate_list, stdin=stdin)

    def launch_self(self, command, args=(), assoc_args=None, *, exit_on_error=True,
                    return_detailed=False, runtime_args=None, obfuscate_list=()):
        """Run appctl ``command``; return the ``ProcessRun`` when
        ``return_detailed`` or else its return code. A failure halts the
        current invocation with the same code when ``exit_on_error``."""
        result = self.launch(command, args, assoc_args, runtime_args=runtime_args,
                             obfuscate_list=obfuscate_list)
        if return_detailed:
            return result
        if result.return_code and exit_on_error:
            raise Halt(result.return_code)
        return result.return_code

    def runcommand(self, command, *, return_="stdout", parse=None, exit_error=True,
                   obfuscate_list=(), stdin=None):
        """Run appctl ``command`` and return part of its outcome.

        ``return_`` is ``"stdout"``, ``"stderr"``, ``"return_code"`` or
        ``"all"``; with ``parse="json"`` STDOUT is decoded as JSON (``None``
        when it is not valid JSON).
        """
        result = self.launch(command, obfuscate_list=obfuscate_list, stdin=stdin)
        if result.return_code and exit_error:
            if result.stderr:
                self.out.write_stderr(result.stderr)
            raise Halt(result.return_code)
        if return_ == "all":
            return result
        if return_ == "return_code":
            return result.return_code
        if return_ == "stderr":
            return result.stderr.rstrip("\r\n")
        stdout = result.stdout.rstrip("\r\n")
        if parse == "json":
            try:
                return json.loads(stdout)
            except ValueError:
                return None
        return stdout
"""Remote execution.

Secret: the syntax of ``ssh`` connection strings, how each transport
(ssh, docker, docker-compose, docker-compose-run, vagrant) builds its
command line, how the remote appctl command is assembled (pre-command,
working directory, forwarded arguments) and how transport failures are
reported.
"""

import re
import shlex
import shutil
import subprocess

from . import messages as _messages

_REMOTE_BINARY = "appctl"
_PRE_CMD_ENV = "APPCTL_SSH_PRE_CMD"
_STRICT_ENV = "APPCTL_STRICT_ARGS_MODE"
_CONNECT_FAILURE = 255
_SSH_URL = re.compile(
    r"^((?P<scheme>docker|docker-compose|docker-compose-run|ssh|vagrant):)?"
    r"(//)?((?P<user>[^@:]+)@)?(?P<host>[^:/~]+)(:(?P<port>\d*))?"
    r"(?P<path>[/~].*)?$")
# Connection keys forwarded to the remote invocation as runtime flags.
_FORWARDED = ("path", "url", "user")


def parse(url):
    """Split a connection string into its parts (missing parts are None)."""
    match = _SSH_URL.match(url or "")
    if not match:
        return {"scheme": None, "user": None, "host": url, "port": None, "path": None}
    bits = match.groupdict()
    return {key: (value or None) for key, value in bits.items()}


def _quote_path(path):
    if path == "~":
        return path
    if path.startswith("~/"):
        return "~/" + shlex.quote(path[2:])
    return shlex.quote(path)


def remote_command(args, bits, env):
    """The shell command run on the remote side."""
    parts = []
    pre = (env.get(_PRE_CMD_ENV) or "").strip().rstrip(";").strip()
    if pre:
        parts.append(pre + ";")
    if bits.get("path"):
        parts.append(f"cd {_quote_path(bits['path'])};")
    if env.get(_STRICT_ENV):
        parts.append(f"{_STRICT_ENV}=1")
    parts.append(_REMOTE_BINARY)
    parts.extend(shlex.quote(a) for a in args)
    return " ".join(parts)


def transport_argv(bits, command, args, tty, debug):
    """The local command line that runs ``command`` remotely."""
    scheme = bits.get("scheme") or "ssh"
    host, user, port = bits.get("host") or "", bits.get("user"), bits.get("port")
    if scheme == "docker":
        argv = ["docker", "exec"]
        if user:
            argv += ["--user", user]
        if tty:
            argv.append("-t")
        return argv + [host, "sh", "-c", command]
    if scheme == "docker-compose":
        argv = ["docker-compose", "exec"]
        if user:
            argv += ["--user", user]
        if not tty:
            argv.append("-T")
        return argv + [host, "sh", "-c", command]
    if scheme == "docker-compose-run":
        argv = ["docker-compose", "run"]
        if user:
            argv += ["--user", user]
        if not tty:
            argv.append("-T")
        return argv + [host] + list(args)
    if scheme == "vagrant":
        return ["vagrant", "ssh", "-c", command, host]
    argv = ["ssh"]
    if port:
        argv += ["-p", str(int(port))]
    argv.append("-t" if tty else "-T")
    argv.append("-vvv" if debug else "-q")
    argv.append(f"{user}@{host}" if user else host)
    return argv + [command]


def _fileno(stream):
    try:
        return stream.fileno()
    except (AttributeError, OSError, ValueError):
        return None


def _isatty(stream):
    try:
        return stream.isatty()
    except (AttributeError, ValueError):
        return False


def forwarded_args(raw_args, connection, runtime_values):
    """Arguments for the remote appctl: the local ones minus ``--ssh``, plus
    connection parameters that were not given at runtime."""
    args = [a for a in raw_args if not (a == "--ssh" or a.startswith("--ssh="))]
    for key in _FORWARDED:
        value = connection.get(key)
        if value not in (None, "") and key not in runtime_values:
            args.append(f"--{key}={value}")
    return args


def run(ssh, raw_args, connection, runtime_values, config, env, out, stdout, stderr):
    """Run the command through the configured transport; return exit code."""
    bits = parse(ssh)
    args = forwarded_args(raw_args, connection, runtime_values)
    tty = not config.get("skip-tty") and _isatty(stdout)
    command = remote_command(args, bits, env)
    argv = transport_argv(bits, command, args, tty, config.debug())
    out.debug(f"Running remote command: {shlex.join(argv)}", group="ssh")
    for stream in (stdout, stderr):
        if hasattr(stream, "flush"):
            stream.flush()
    executable = shutil.which(argv[0], path=env.get("PATH"))
    if executable is None:
        out.error(_messages.ssh_connection_failed())
        return _CONNECT_FAILURE
    out_fd, err_fd = _fileno(stdout), _fileno(stderr)
    try:
        proc = subprocess.run(
            [executable] + argv[1:], env=dict(env),
            stdout=out_fd if out_fd is not None else subprocess.PIPE,
            stderr=err_fd if err_fd is not None else subprocess.PIPE)
    except OSError:
        out.error(_messages.ssh_connection_failed())
        return _CONNECT_FAILURE
    if out_fd is None and proc.stdout:
        stdout.write(proc.stdout.decode(errors="replace"))
    if err_fd is None and proc.stderr:
        stderr.write(proc.stderr.decode(errors="replace"))
    if proc.returncode == _CONNECT_FAILURE:
        out.error(_messages.ssh_connection_failed())
    return proc.returncode

